     7	  minAmountCents: number;
     8	  maxDiscountCents: number | null;
     9	  validFrom: string;
    10	  validUntil: string;
    11	  status: "ACTIVE" | "DISABLED";
    12	  usageLimit: number | null;
    13	  usedCount: number;
    14	}
    15	
    16	interface CouponRow {
    17	  code: string;
    18	  type: Coupon["type"];
    19	  value: number;
    20	  min_amount_cents: number;
    21	  max_discount_cents: number | null;
    22	  valid_from: string;
    23	  valid_until: string;
    24	  status: Coupon["status"];
    25	  usage_limit: number | null;
    26	  used_count: number;
    27	}
    28	
    29	const toCoupon = (r: CouponRow): Coupon => ({
    30	  code: r.code,
    31	  type: r.type,
    32	  value: r.value,
    33	  minAmountCents: r.min_amount_cents,
    34	  maxDiscountCents: r.max_discount_cents,
    35	  validFrom: r.valid_from,
    36	  validUntil: r.valid_until,
    37	  status: r.status,
    38	  usageLimit: r.usage_limit,
    39	  usedCount: r.used_count,
    40	});
    41	
    42	export class CouponRepository {
    43	  constructor(private readonly db: Db) {}
    44	
    45	  insert(c: Omit<Coupon, "usedCount">): Coupon {
    46	    this.db
    47	      .prepare(
    48	        `INSERT INTO coupons (code, type, value, min_amount_cents, max_discount_cents,
    49	                              valid_from, valid_until, status, usage_limit)
    50	         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    51	      )
    52	      .run(c.code, c.type, c.value, c.minAmountCents, c.maxDiscountCents, c.validFrom, c.validUntil, c.status, c.usageLimit);
    53	    return this.findByCode(c.code)!;
    54	  }
    55	
    56	  findByCode(code: string): Coupon | undefined {
    57	    const row = this.db.prepare("SELECT * FROM coupons WHERE code = ?").get(code) as CouponRow | undefined;
    58	    return row && toCoupon(row);
    59	  }
    60	}
